CREATE TYPE bpm_item_kind AS ENUM ('SECTION','SUBSECTION','GROUP','CRITERION');
CREATE TYPE bpm_criticality AS ENUM ('CRITICA','MAYOR','MENOR');
CREATE TYPE bpm_response_value AS ENUM ('C','CP','IT','NA');
CREATE TYPE bpm_template_status AS ENUM ('DRAFT','PUBLISHED');
CREATE TABLE bpm_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code varchar(80) NOT NULL UNIQUE,name varchar(200) NOT NULL,description text,current_published_version_id uuid,version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(btrim(code)<>'' AND code=upper(btrim(code))),CHECK(btrim(name)<>''));
CREATE TABLE bpm_template_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),template_id uuid NOT NULL REFERENCES bpm_templates(id) ON DELETE RESTRICT,version_number integer NOT NULL CHECK(version_number>0),status bpm_template_status NOT NULL DEFAULT 'DRAFT',publication_note text,published_at timestamptz,published_by_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(template_id,version_number),CHECK((status='DRAFT' AND published_at IS NULL AND published_by_user_id IS NULL) OR (status='PUBLISHED' AND published_at IS NOT NULL AND published_by_user_id IS NOT NULL)));
ALTER TABLE bpm_templates ADD CONSTRAINT bpm_templates_current_version_fk FOREIGN KEY(current_published_version_id) REFERENCES bpm_template_versions(id) ON DELETE RESTRICT;
CREATE TABLE bpm_template_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),template_version_id uuid NOT NULL REFERENCES bpm_template_versions(id) ON DELETE RESTRICT,parent_item_id uuid,item_kind bpm_item_kind NOT NULL,source_code varchar(120),display_code varchar(120),title text NOT NULL,description text,sort_order integer NOT NULL DEFAULT 0,is_evaluable boolean NOT NULL DEFAULT false,default_criticality bpm_criticality,source_reference varchar(500),source_row_number integer,source_parent_code_raw varchar(120),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,template_version_id),UNIQUE(template_version_id,parent_item_id,sort_order),CHECK(sort_order>=0),CHECK(btrim(title)<>''),CHECK((item_kind='CRITERION' AND is_evaluable) OR (item_kind<>'CRITERION' AND NOT is_evaluable)),CHECK((item_kind='CRITERION' AND default_criticality IS NOT NULL) OR (item_kind<>'CRITERION' AND default_criticality IS NULL)),FOREIGN KEY(parent_item_id,template_version_id) REFERENCES bpm_template_items(id,template_version_id) ON DELETE RESTRICT);
CREATE UNIQUE INDEX bpm_item_source_row_unique ON bpm_template_items(template_version_id,source_reference,source_row_number) WHERE source_reference IS NOT NULL AND source_row_number IS NOT NULL;
CREATE UNIQUE INDEX bpm_item_display_code_unique ON bpm_template_items(template_version_id,display_code) WHERE display_code IS NOT NULL;
CREATE INDEX bpm_items_parent_order_idx ON bpm_template_items(template_version_id,parent_item_id,sort_order);

CREATE OR REPLACE FUNCTION bpm_template_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.code IS DISTINCT FROM OLD.code THEN RAISE EXCEPTION 'template code immutable'; END IF; IF NEW.current_published_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM bpm_template_versions v WHERE v.id=NEW.current_published_version_id AND v.template_id=COALESCE(NEW.id,OLD.id) AND v.status='PUBLISHED') THEN RAISE EXCEPTION 'current version invalid'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION bpm_version_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' AND OLD.status='PUBLISHED' THEN RAISE EXCEPTION 'published version immutable'; END IF; IF TG_OP='UPDATE' THEN IF OLD.status='PUBLISHED' THEN RAISE EXCEPTION 'published version immutable'; END IF; IF NEW.status='PUBLISHED' AND NOT EXISTS(SELECT 1 FROM bpm_template_items WHERE template_version_id=NEW.id AND item_kind='CRITERION' AND is_evaluable) THEN RAISE EXCEPTION 'published version requires criterion'; END IF; IF NEW.status='PUBLISHED' AND (NEW.template_id IS DISTINCT FROM OLD.template_id OR NEW.version_number IS DISTINCT FROM OLD.version_number) THEN RAISE EXCEPTION 'invalid publication transition'; END IF; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION bpm_item_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE typ bpm_item_kind; BEGIN IF EXISTS(SELECT 1 FROM bpm_template_versions WHERE id=COALESCE(NEW.template_version_id,OLD.template_version_id) AND status='PUBLISHED') THEN RAISE EXCEPTION 'published items immutable'; END IF; IF TG_OP IN ('INSERT','UPDATE') AND NEW.parent_item_id IS NOT NULL THEN IF NEW.parent_item_id=NEW.id THEN RAISE EXCEPTION 'self parent'; END IF; SELECT item_kind INTO typ FROM bpm_template_items WHERE id=NEW.parent_item_id AND template_version_id=NEW.template_version_id; IF typ IS NULL OR typ='CRITERION' THEN RAISE EXCEPTION 'invalid parent'; END IF; IF EXISTS(WITH RECURSIVE a AS(SELECT parent_item_id FROM bpm_template_items WHERE id=NEW.parent_item_id AND template_version_id=NEW.template_version_id UNION ALL SELECT e.parent_item_id FROM bpm_template_items e JOIN a ON e.id=a.parent_item_id WHERE e.template_version_id=NEW.template_version_id) SELECT 1 FROM a WHERE parent_item_id=NEW.id) THEN RAISE EXCEPTION 'cycle'; END IF; END IF; IF TG_OP='UPDATE' AND NEW.item_kind='CRITERION' AND EXISTS(SELECT 1 FROM bpm_template_items WHERE parent_item_id=NEW.id) THEN RAISE EXCEPTION 'criterion cannot parent'; END IF; RETURN COALESCE(NEW,OLD); END $$;
CREATE TRIGGER bpm_templates_guard BEFORE INSERT OR UPDATE ON bpm_templates FOR EACH ROW EXECUTE FUNCTION bpm_template_guard();
CREATE TRIGGER bpm_versions_guard BEFORE UPDATE OR DELETE ON bpm_template_versions FOR EACH ROW EXECUTE FUNCTION bpm_version_guard();
CREATE TRIGGER bpm_items_guard BEFORE INSERT OR UPDATE OR DELETE ON bpm_template_items FOR EACH ROW EXECUTE FUNCTION bpm_item_guard();
CREATE TRIGGER bpm_templates_version BEFORE UPDATE ON bpm_templates FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_version();
CREATE TRIGGER bpm_versions_version BEFORE UPDATE ON bpm_template_versions FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_version();
CREATE TRIGGER bpm_items_version BEFORE UPDATE ON bpm_template_items FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_version();
